const captureBetweenChannelBatchBaseline = `-- name: CaptureBetweenChannelBatchBaseline :execrows
INSERT INTO firmware_rollout_evidence (
    rollout_id,
    member_id,
    org_id,
    phase,
    window_start,
    window_end,
    observed_at,
    avg_hashrate_hs,
    avg_power_w,
    avg_temperature_c,
    error_count,
    sample_count
)
SELECT member.rollout_id,
       member.id,
       member.org_id,
       'baseline',
       $1,
       $2,
       CASE WHEN MAX(metrics.time) >= $3 THEN MAX(metrics.time) ELSE NULL END,
       CASE WHEN MAX(metrics.time) >= $3 THEN AVG(metrics.hash_rate_hs)::float8 ELSE NULL END,
       CASE WHEN MAX(metrics.time) >= $3 THEN AVG(metrics.power_w)::float8 ELSE NULL END,
       CASE WHEN MAX(metrics.time) >= $3 THEN AVG(metrics.temp_c)::float8 ELSE NULL END,
       CASE
           WHEN MAX(metrics.time) >= $3 THEN (
               SELECT COUNT(*)::bigint
               FROM errors error_row
               WHERE error_row.device_id = member.device_id
                 AND error_row.org_id = member.org_id
                 AND error_row.last_seen_at >= $1
                 AND error_row.first_seen_at <= $2
           )
           ELSE NULL
       END,
       CASE WHEN MAX(metrics.time) >= $3 THEN COUNT(metrics.time)::bigint ELSE NULL END
FROM firmware_rollout_member member
JOIN device
  ON device.id = member.device_id
 AND device.org_id = member.org_id
LEFT JOIN device_metrics metrics
  ON metrics.device_identifier = device.device_identifier
 AND metrics.time >= $1
 AND metrics.time <= $2
WHERE member.rollout_id = $4
  AND member.batch_id = $5
  AND member.org_id = $6
GROUP BY member.rollout_id,
         member.id,
         member.org_id,
         member.device_id,
         member.position
ON CONFLICT (member_id, phase) DO NOTHING
`

